"use client";

export function ConicGradientTailwind({ children }: { children?: React.ReactNode }) {
  const conic = "conic-gradient(from 0deg, #ff3d7f, #ffb020, #18d6a3, #5b6cff, #ff3d7f)";
  return (
    <div className="relative isolate flex h-[360px] w-full items-center justify-center overflow-hidden rounded-[20px] border border-zinc-800 bg-[#07070b]">
      <div aria-hidden className="absolute left-[16%] top-1/2 aspect-square w-[68%] -translate-y-1/2 animate-[spin_14s_linear_infinite] rounded-full opacity-60 blur-[60px]" style={{ background: conic }} />
      <div aria-hidden className="absolute left-[22.5%] top-1/2 aspect-square w-[55%] -translate-y-1/2 animate-[spin_14s_linear_infinite] rounded-full opacity-80 blur-[18px] [mask-image:radial-gradient(circle,#000_30%,transparent_70%)]" style={{ background: conic }} />
      <div className="relative text-center">
        {children ?? (
          <>
            <h3 className="text-3xl font-bold tracking-tight text-zinc-50">Conic Gradient</h3>
            <p className="mt-2 text-sm text-zinc-400">A slow-turning spectrum core with a soft halo.</p>
          </>
        )}
      </div>
    </div>
  );
}
